mapper.select:
select id, doctor_name, title, hospital, account, password, phone, role, status, is_deleted, create_time, update_time from sys_doctor WHERE is_deleted = 0
AND doctor_name LIKE CONCAT('%', #{doctorName}, '%')
AND account LIKE CONCAT('%', #{account}, '%')
AND role = #{role}
ORDER BY ${sortField} ${sortOrder}
